using System;

class Program
{
    static void Main()
    {
        // String declaration and initialization
        string firstName = "Alice";
        string lastName = "Johnson";

        // Concatenation — creates a NEW string each time
        string fullName = firstName + " " + lastName;
        Console.WriteLine(fullName); // Alice Johnson

        // String interpolation — preferred for readability
        string greeting = $"Hello, {firstName} {lastName}!";
        Console.WriteLine(greeting); // Hello, Alice Johnson!

        // Common string methods — each returns a NEW string
        string upper = firstName.ToUpper();        // ALICE
        string lower = firstName.ToLower();        // alice
        int length = firstName.Length;             // 5
        bool contains = fullName.Contains("ice"); // True
        string replaced = fullName.Replace("Alice", "Bob"); // Bob Johnson
        string sub = fullName.Substring(0, 5);     // Alice
        bool startsWith = fullName.StartsWith("Ali"); // True
        bool endsWith = fullName.EndsWith("son");  // True

        // String is immutable — original is never changed
        Console.WriteLine(fullName); // Still "Alice Johnson"

        // Verbatim strings — no escape sequences needed
        string path = @"C:\Users\Alice\Documents";
        string multiline = @"
            Line 1
            Line 2
            Line 3
        ";
        Console.WriteLine(path);
    }
}

