using System;

class Program
{
    static void Main()
    {
        // Declare and initialize with values
        int[] scores = new int[] { 95, 82, 77, 64, 91 };

        // Shorthand syntax (compiler infers the type and size)
        string[] names = { "Alice", "Bob", "Charlie" };

        // Access elements by zero-based index
        Console.WriteLine(scores[0]);  // 95 (first element)
        Console.WriteLine(names[2]);   // Charlie (third element)

        // Modify an element
        scores[0] = 100;
        Console.WriteLine(scores[0]);  // 100

        // Array length (number of elements)
        Console.WriteLine(scores.Length); // 5

        // Loop through with foreach (read-only)
        Console.WriteLine("\nScores:");
        foreach (int score in scores)
        {
            Console.WriteLine(score);
        }

        // Loop with index using for
        Console.WriteLine("\nNames with index:");
        for (int i = 0; i < names.Length; i++)
        {
            Console.WriteLine($"{i}: {names[i]}");
        }

        // Multidimensional array
        int[] matrix = new int[2, 3] { { 1, 2, 3 }, { 4, 5, 6 } };
        Console.WriteLine(matrix[1, 2]); // 6
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // Create a list of strings
        List<string> tasks = new List<string>();

        // Add items
        tasks.Add("Buy groceries");
        tasks.Add("Write report");
        tasks.Add("Call dentist");
        Console.WriteLine($"Count: {tasks.Count}"); // 3

        // Insert at a specific position
        tasks.Insert(1, "Pick up dry cleaning");

        // Remove an item
        tasks.Remove("Write report");

        // Access by index (like an array)
        Console.WriteLine(tasks[0]); // Buy groceries

        // Check if an item exists
        bool hasTask = tasks.Contains("Call dentist"); // True

        // Iterate
        Console.WriteLine("\nYour tasks:");
        foreach (string task in tasks)
        {
            Console.WriteLine($"- {task}");
        }

        // Dictionary — key-value pairs
        Dictionary<string, int> ages = new Dictionary<string, int>
        {
            { "Alice", 30 },
            { "Bob", 25 },
            { "Charlie", 35 }
        };
        Console.WriteLine($"\nBob's age: {ages["Bob"]}"); // 25
    }
}

using System;

class Person
{
    public string Name { get; set; }
}

class Program
{
    static void Main()
    {
        Person? person = GetPerson(); // Might return null

        // Unsafe — crashes if person is null
        // Console.WriteLine(person.Name.Length);

        // Safe: null-conditional operator (?.)
        int? length = person?.Name?.Length;
        Console.WriteLine(length ?? 0); // 0 if null

        // Safe: null-coalescing operator (??)
        string displayName = person?.Name ?? "Unknown";
        Console.WriteLine(displayName);
    }

    static Person GetPerson()
    {
        return null; // Simulating a failed lookup
    }
}
